INSERT INTO cfg.PARAMETRO (CLIENTE, CLAVE, VALOR, DESCRIPCION) VALUES (N'486', N'PREFIJO_CUENTA2', N'486-', N'Prefijo de la cuenta en CYBER');
INSERT INTO cfg.PARAMETRO (CLIENTE, CLAVE, VALOR, DESCRIPCION) VALUES (N'486', N'CYBER_TABLA_ABANDONO', N'RCVRY.RPT_DAT_486_1', N'Tabla de CYBER de donde las vistas toman ABAN_SR y ABAN_CR (alias r de cfg.CYBER_CAMPO; 19/11: RPT_DAT_486_1 tal como la dejó PROC_DAT_486, sin ejecutarlo). Para tomarlos de otra tabla, cambiar este parámetro y CYBER_LLAVE_ABANDONO');
INSERT INTO cfg.PARAMETRO (CLIENTE, CLAVE, VALOR, DESCRIPCION) VALUES (N'486', N'CYBER_LLAVE_ABANDONO', N'CUENTA', N'Columna de CYBER_TABLA_ABANDONO con la cuenta (486-folio) que se cruza con DELQMST.DMACCT');
INSERT INTO cfg.PARAMETRO (CLIENTE, CLAVE, VALOR, DESCRIPCION) VALUES (N'486', N'VISTAS_USUARIO', N'1', N'1 (18/11) = al terminar la actualización y la asignación, y cuando suben los saldos, se bajan de CYBER los campos de las vistas (directo de DELQMST y RPT_DAT_486_1, sin ejecutar el store desde el 19/11) y se arma la tabla de cada usuario (cfg.VISTA_USUARIO: AEM, MIS); 0 = no se actualizan');
INSERT INTO cfg.PARAMETRO (CLIENTE, CLAVE, VALOR, DESCRIPCION) VALUES (N'486', N'VALIDAR_LAYOUT', N'1', N'1 (17/11) = si a un archivo le falta cualquier campo que toma el proceso (cfg.ARCHIVO_COLUMNA, obligatorio u opcional), la corrida se detiene antes de tocar el DAT y se avisa al equipo de asignaciones (VALIDACION_ENTRADA_486); 0 = como antes: solo los obligatorios detienen');
INSERT INTO cfg.PARAMETRO (CLIENTE, CLAVE, VALOR, DESCRIPCION) VALUES (N'486', N'VALIDAR_DATOS', N'1', N'1 (17/11) = cada archivo se revisa con las reglas de cfg.VALIDACION_DATO (importes, teléfonos, correos, catálogos, cuentas repetidas, volumen); si una supera su tolerancia, la corrida se detiene antes de tocar el DAT y se avisa (VALIDACION_ENTRADA_486); 0 = no se revisan');
INSERT INTO cfg.PARAMETRO (CLIENTE, CLAVE, VALOR, DESCRIPCION) VALUES (N'486', N'TOPE_DEVOLUCION_PCT', N'', N'Vacío = sin tope: la base maestra se trabaja como llega. Con un número (ej. 10) se detiene si la devolución de un segmento supera ese %');
INSERT INTO cfg.PARAMETRO (CLIENTE, CLAVE, VALOR, DESCRIPCION) VALUES (N'486', N'DMSTATUS_RETIRO', N'R', N'dmstatus que se pone en CYBER al retirar (prog15.prg: u8activo = ''R'')');
INSERT INTO cfg.PARAMETRO (CLIENTE, CLAVE, VALOR, DESCRIPCION) VALUES (N'486', N'ASIG_REQUIERE_ACT', N'1', N'1 = la asignación solo corre si la actualización del mismo día terminó OK (la asignación siempre llega después)');
INSERT INTO cfg.PARAMETRO (CLIENTE, CLAVE, VALOR, DESCRIPCION) VALUES (N'486', N'RESPALDOS_A_CONSERVAR', N'15', N'Corridas con respaldo del DAT que se conservan para retroceso');
INSERT INTO cfg.PARAMETRO (CLIENTE, CLAVE, VALOR, DESCRIPCION) VALUES (N'486', N'ALERTA_NUEVAS', N'100', N'Más cuentas nuevas que esto dispara la alerta (aem_alerta)');
INSERT INTO cfg.PARAMETRO (CLIENTE, CLAVE, VALOR, DESCRIPCION) VALUES (N'486', N'DIAS_FE_REG', N'30', N'FE_REG = FE_REC + días');
INSERT INTO cfg.PARAMETRO (CLIENTE, CLAVE, VALOR, DESCRIPCION) VALUES (N'486', N'NEGATIVO_MODO', N'CERO', N'Importes negativos en SCBSDOS (DMCURBAL, U1PAGMIN, DMAMTDLQ) y scripts de saldos: CERO (decisión 30/10: saldo <= 0 se retira, sube en cero antes del retiro) | ABS_LEGADO | SIGNO');
INSERT INTO cfg.PARAMETRO (CLIENTE, CLAVE, VALOR, DESCRIPCION) VALUES (N'486', N'LADAS_2_DIGITOS', N'33,55,56,81', N'Ladas de 2 dígitos (telbnx.prg); el resto son de 3');
INSERT INTO cfg.PARAMETRO (CLIENTE, CLAVE, VALOR, DESCRIPCION) VALUES (N'486', N'LADAS_044', N'55,56', N'Celulares de estas ladas van con área 044; el resto con 045');
INSERT INTO cfg.PARAMETRO (CLIENTE, CLAVE, VALOR, DESCRIPCION) VALUES (N'486', N'TEL_INVALIDOS', N'1000000000,9999999999,0999999999,1111111111,4444444444,5555555555,5000000000', N'Teléfonos que nunca se mandan (telbnx.prg + G4_025_TELEFONOS); además se descartan los que empiezan con 0');
INSERT INTO cfg.PARAMETRO (CLIENTE, CLAVE, VALOR, DESCRIPCION) VALUES (N'486', N'TEL_EXIGIR_PNM', N'1', N'1 = el teléfono que no está en el plan de numeración se descarta (G4_025_TELEFONOS, decisión 01/11); 0 = sale como fijo (telbnx.prg)');
INSERT INTO cfg.PARAMETRO (CLIENTE, CLAVE, VALOR, DESCRIPCION) VALUES (N'486', N'ARRIBO_AUTOMATICO', N'1', N'1 (07/11: proceso autónomo; orden del 17/11 y 19/11) = con los saldos arriba el job manda los gescar de nuevas, reasignadas y sin teléfono y corre la depuración de teléfonos (con bandera); si cuadra avisa para subir el SCBTEL y corre la de correos; al final confirma. 0 = a mano con ops.sp_arribar_cyber y ops.sp_arribo_gescar_sintel');
INSERT INTO cfg.PARAMETRO (CLIENTE, CLAVE, VALOR, DESCRIPCION) VALUES (N'486', N'ARCHIVOS_DESPUES_SALDOS', N'GESCAR_NVA,GESCAR_REA,GESCAR_SINTEL', N'Con ARRIBO_AUTOMATICO = 1, archivos de la asignación que se escriben y avisan hasta que suben los saldos (paso ARRIBO SALDOS). GESCAR_SINTEL siempre espera a los saldos (19/11)');
INSERT INTO cfg.PARAMETRO (CLIENTE, CLAVE, VALOR, DESCRIPCION) VALUES (N'486', N'ARCHIVOS_DESPUES_DEPURACION_TEL', N'SCBTEL', N'Con ARRIBO_AUTOMATICO = 1, archivos que se escriben y avisan hasta que la depuración de teléfonos queda OK (el store inactiva lo que no está en la remesa y el SCBTEL activa lo nuestro)');
INSERT INTO cfg.PARAMETRO (CLIENTE, CLAVE, VALOR, DESCRIPCION) VALUES (N'486', N'ARRIBO_MIN_PCT', N'95', N'% de lo pendiente al terminar la asignación (cuentas y domicilios en DELQMST, teléfonos en PHONE_G1) que ya debe estar en CYBER para dar por subido el SCBSDOS o el SCBTEL');
INSERT INTO cfg.PARAMETRO (CLIENTE, CLAVE, VALOR, DESCRIPCION) VALUES (N'486', N'CYBER_REMESA_TEL_COLUMNAS', N'CUENTA,AREA,TELEFONO,TIPOTEL', N'Columnas de RCVRY.JSP_TAB_TEL_REMESA_486 en el orden de sub_mst.TXT (confirmar con LOAD_TEL_REMESA.CTL)');
INSERT INTO cfg.PARAMETRO (CLIENTE, CLAVE, VALOR, DESCRIPCION) VALUES (N'486', N'CYBER_REMESA_MAIL_COLUMNAS', N'CUENTA,CORREO', N'Columnas de RCVRY.JSP_TAB_MAIL_REMESA_486 en el orden de sub_mail.TXT (confirmar con LOAD_MAIL_REMESA.CTL)');
INSERT INTO cfg.PARAMETRO (CLIENTE, CLAVE, VALOR, DESCRIPCION) VALUES (N'486', N'CYBER_HOSTUP_EXPR', N'to_char(DMHOSTUP, ''YYYYMMDD'')', N'Validación de saldos del equipo (val.txt, 15/11): expresión de Oracle con la fecha de DMHOSTUP en AAAAMMDD; el arribo agrupa las cuentas activas del 486 por ella. Si DMHOSTUP no es DATE, ajustarla (ej. DMHOSTUP si ya viene como texto AAAAMMDD). Vacío = se detecta el SCBSDOS por cuentas y domicilios pendientes');
INSERT INTO cfg.PARAMETRO (CLIENTE, CLAVE, VALOR, DESCRIPCION) VALUES (N'486', N'ARRIBO_SDOS_MIN_PCT', N'100', N'% de las cuentas del SCBSDOS que deben tener DMHOSTUP del día para dar por subidos los saldos (100 = que el número coincida)');
INSERT INTO cfg.PARAMETRO (CLIENTE, CLAVE, VALOR, DESCRIPCION) VALUES (N'486', N'CYBER_COLUMNA_DOMICILIO', N'DMADDR1', N'Columna de RCVRY.DELQMST con el domicilio del SCBSDOS; el arribo automático la usa para saber si ya subió el SCBSDOS aunque no haya cuentas nuevas (vacío = no se compara)');
INSERT INTO cfg.PARAMETRO (CLIENTE, CLAVE, VALOR, DESCRIPCION) VALUES (N'486', N'RETIRO_AUTOMATICO', N'1', N'1 = las devoluciones de la asignación y la actualización se aplican solas si no superan el tope, y después se escriben los archivos, ZIP y correo, se ejecuta RETIRO en CYBER y se copia la devolución a RUTA_DEVOLUCION_CYBER; 0 = manual');
INSERT INTO cfg.PARAMETRO (CLIENTE, CLAVE, VALOR, DESCRIPCION) VALUES (N'486', N'RETIRO_TOPE_PCT_ASIG', N'50', N'En la asignación, si la devolución de un segmento supera este % de sus cuentas en el DAT, el retiro queda manual y se manda HALLAZGO_486');
INSERT INTO cfg.PARAMETRO (CLIENTE, CLAVE, VALOR, DESCRIPCION) VALUES (N'486', N'RETIRO_TOPE_PCT_ACT', N'50', N'En la actualización, si la devolución de un segmento supera este % de sus cuentas en el DAT, el retiro queda manual y se manda HALLAZGO_486');
INSERT INTO cfg.PARAMETRO (CLIENTE, CLAVE, VALOR, DESCRIPCION) VALUES (N'486', N'RETIRO_CYBER_AUTOMATICO', N'1', N'1 (07/11) = el cierre del retiro también ejecuta RETIRO en CYBER; la copia de la devolución a Cyber_00 sigue a mano mientras RUTA_DEVOLUCION_CYBER esté vacío. 0 = RETIRO en CYBER a mano (EXEC ops.sp_retiro_cerrar <id>, @con_cyber = 1)');
INSERT INTO cfg.PARAMETRO (CLIENTE, CLAVE, VALOR, DESCRIPCION) VALUES (N'486', N'RUTA_DEVOLUCION_CYBER', N'', N'Carpeta donde CYBER toma el archivo de devolución MX_G1MCT_DVBJIG_* (\\192.168.50.1\Cyber_00\dev\). Vacío (03/11: el servidor no tiene acceso a Cyber_00) = se copia a mano desde la carpeta de la corrida');
INSERT INTO cfg.PARAMETRO (CLIENTE, CLAVE, VALOR, DESCRIPCION) VALUES (N'486', N'AVISO_ARCHIVOS', N'1', N'1 = en cuanto se escriben los planos que se suben a CYBER se manda ARCHIVOS_LISTOS_486 al equipo de asignaciones (ops.sp_aviso_archivos)');
INSERT INTO cfg.PARAMETRO (CLIENTE, CLAVE, VALOR, DESCRIPCION) VALUES (N'486', N'ARCHIVOS_ARRIBO', N'SCBSDOS,SCBSDOS_ETI,SCBTEL,GESCAR_NVA,GESCAR_REA,GESCAR_SINTEL,GESCAR_RETIRO,SCBPAG', N'Archivos planos que el equipo de asignaciones sube con el cargador de CYBER (van en el aviso de archivos listos)');
INSERT INTO cfg.PARAMETRO (CLIENTE, CLAVE, VALOR, DESCRIPCION) VALUES (N'486', N'EXPORTAR_AUTOMATICO', N'1', N'1 = cada corrida escribe sus archivos y scripts al terminar OK (ops.sp_exportar_salidas); 0 = a mano');
INSERT INTO cfg.PARAMETRO (CLIENTE, CLAVE, VALOR, DESCRIPCION) VALUES (N'486', N'ACT_CYBER_AUTOMATICO', N'1', N'1 (07/11) = al terminar la actualización el job ejecuta en CYBER ACT_SALDOS, ACT_VENCIDO, ACT_PAGMIN y ACT_PVS_REE (ops.sp_act_cyber); 0 = a mano');
INSERT INTO cfg.PARAMETRO (CLIENTE, CLAVE, VALOR, DESCRIPCION) VALUES (N'486', N'BLANQUEO_AUTOMATICO', N'1', N'1 (07/11) = el blanqueo de status (días DIAS_BLANQUEO_STATUS) se baja, se arma y se ejecuta en CYBER en cuanto subió el SCBSDOS (ops.sp_blanqueo_automatico); 0 = a mano');
INSERT INTO cfg.PARAMETRO (CLIENTE, CLAVE, VALOR, DESCRIPCION) VALUES (N'486', N'CONFIRMACION_AUTOMATICA', N'1', N'1 (07/11) = al terminar OK las depuraciones de correos y teléfonos se marca el fin del arribo y se manda CONFIRMACION_ASIG_486 (ops.sp_confirmar_asignacion); 0 = a mano');
INSERT INTO cfg.PARAMETRO (CLIENTE, CLAVE, VALOR, DESCRIPCION) VALUES (N'486', N'CUADRE_AUTOMATICO', N'1', N'1 = el job cuadra los pagos del SCBPAG contra CYBER y solo avisa (HALLAZGO_486) si a la hora límite falta alguno (ops.sp_cuadre_automatico)');
INSERT INTO cfg.PARAMETRO (CLIENTE, CLAVE, VALOR, DESCRIPCION) VALUES (N'486', N'CUADRE_PAGOS_HORA_LIMITE', N'17:00', N'Hora a la que el cuadre automático deja de esperar al SCBPAG y avisa los pagos que no subieron');
INSERT INTO cfg.PARAMETRO (CLIENTE, CLAVE, VALOR, DESCRIPCION) VALUES (N'486', N'CYBER_SENTENCIAS_POR_BLOQUE', N'200', N'Sentencias por bloque PL/SQL al ejecutar en CYBER');
INSERT INTO cfg.PARAMETRO (CLIENTE, CLAVE, VALOR, DESCRIPCION) VALUES (N'486', N'CYBER_VALIDADOR_TELEFONOS', N'1', N'1 = el script TEL_BORRA inserta el renglón del día en RCVRY.JSP_VALIDADOR_TELEFONOS con el total de teléfonos (JSP_TELEFONOS_REMESA_486 lo completa)');
INSERT INTO cfg.PARAMETRO (CLIENTE, CLAVE, VALOR, DESCRIPCION) VALUES (N'486', N'TELBAJ_LINKED_SERVER', N'192.168.50.53', N'Servidor vinculado al SQL Server de CYBER donde están telbaj, telbaj1 y TENOVA1 (como G4_025_TELEFONOS)');
INSERT INTO cfg.PARAMETRO (CLIENTE, CLAVE, VALOR, DESCRIPCION) VALUES (N'486', N'TELBAJ_GRUPO', N'1', N'Grupo del 486 en telbaj (TELBAJ_G1)');
INSERT INTO cfg.PARAMETRO (CLIENTE, CLAVE, VALOR, DESCRIPCION) VALUES (N'486', N'TELBAJ_TABLAS', N'cyber.dbo.telbaj,cyber.dbo.telbaj1,tenova.dbo.TENOVA1', N'Tablas de quejas en ese servidor (columnas grupo, cuenta, telo, telpho)');
INSERT INTO cfg.PARAMETRO (CLIENTE, CLAVE, VALOR, DESCRIPCION) VALUES (N'486', N'PNM_TABLA', N'CYBER.dbo.CAT_PNM', N'Plan de numeración vigente en la misma instancia (columnas LADA, SERIE, NUMINI, NUMFIN, TIPORED); vacío = solo lo migrado');
INSERT INTO cfg.PARAMETRO (CLIENTE, CLAVE, VALOR, DESCRIPCION) VALUES (N'486', N'TEL_DAT_LADAS_2', N'33,55,81', N'op9.prg: ladas de 2 dígitos al guardar los teléfonos de cuentas nuevas en el DAT');
INSERT INTO cfg.PARAMETRO (CLIENTE, CLAVE, VALOR, DESCRIPCION) VALUES (N'486', N'TEL_DAT_AREA_MOVIL', N'045', N'op9.prg: área de los celulares al guardarlos en el DAT');
INSERT INTO cfg.PARAMETRO (CLIENTE, CLAVE, VALOR, DESCRIPCION) VALUES (N'486', N'CORREOS_INVALIDOS', N'notiene@hotmail.com,notiene@gmail.com,notienecorreo@hotmail.com,notiene@mail.com,notiene@email.com', N'email.PRG: correos que no se mandan a CYBER');
INSERT INTO cfg.PARAMETRO (CLIENTE, CLAVE, VALOR, DESCRIPCION) VALUES (N'486', N'CORREOS_EXCLUIR_MALOS', N'1', N'1 = EMAILMALO también se quita de sub_mail.TXT (decisión: sí se aplica)');
INSERT INTO cfg.PARAMETRO (CLIENTE, CLAVE, VALOR, DESCRIPCION) VALUES (N'486', N'CYBER_BANDERA_CORREOS', N'416', N'id_proc de RCVRY.RPT_LOG_CYBER_REG que se enciende y apaga al actualizar correos (ACTIVA/INACTIVA_BANDERA.SQL)');
INSERT INTO cfg.PARAMETRO (CLIENTE, CLAVE, VALOR, DESCRIPCION) VALUES (N'486', N'CYBER_PROC_CORREOS', N'RCVRY.JSP_CORREOS_486', N'Procedimiento de CYBER que purga y agrega los correos (INSERTA_MAIL.sql)');
INSERT INTO cfg.PARAMETRO (CLIENTE, CLAVE, VALOR, DESCRIPCION) VALUES (N'486', N'STATUS_NO_BLANQUEAR', N'GS,PP,LQ,NP,PR,CD,CC,FA', N'status.prg: status que no se blanquean (REQ 2021-051124)');
INSERT INTO cfg.PARAMETRO (CLIENTE, CLAVE, VALOR, DESCRIPCION) VALUES (N'486', N'DIAS_BLANQUEO_STATUS', N'1-10', N'status.prg: días del mes en que se blanquea status');
INSERT INTO cfg.PARAMETRO (CLIENTE, CLAVE, VALOR, DESCRIPCION) VALUES (N'486', N'ETIQUETADO_CAMPOS', N'SALDO1,SALDO2,SALDO3,RIESGO,PVS,TIPO,CAPITAL,SEGMENTO,PAG_MIN,ETIQUETA,TRAMO,SEG,SDO_VDO,NOMBRE2,ESTRA3,DES_PROD,ETIQUETA1,ETIQUETA5', N'ops.sp_etiquetar_campo: columnas del DAT que Operación puede etiquetar');
INSERT INTO cfg.PARAMETRO (CLIENTE, CLAVE, VALOR, DESCRIPCION) VALUES (N'486', N'ETIQUETADO_ALIAS', N'SEG_CICLO=TRAMO,CLASIFICA=ESTRA3,ETIQUETA2=DES_PROD,ETIQUETA3=SEG,ETIQUETA4=RIESGO,LEYENDA=NOMBRE2,SALDO_VEN=SDO_VDO,ETIQUETA10=ETIQUETA,MORA=ETIQUETA1', N'ETIQUETAS486.xlsx: nombre en el DAT de Operación = columna de nuestro DAT (ETIQUETA6 sale de la base maestra: REE, catálogos ETIQUETA6_TDC y ETIQUETA6_CONSUMO)');
INSERT INTO cfg.PARAMETRO (CLIENTE, CLAVE, VALOR, DESCRIPCION) VALUES (N'486', N'CORREO_PRUEBA_PARA', N'', N'Pruebas de entorno (20/11): si tiene una dirección, todos los correos van solo ahí con [PRUEBA] en el asunto. Lo pone y lo quita ops.sp_prueba_modo; vacío en producción');
INSERT INTO cfg.PARAMETRO (CLIENTE, CLAVE, VALOR, DESCRIPCION) VALUES (N'486', N'CYBER_SOLO_LECTURA', N'0', N'Pruebas de entorno (20/11): 1 = ningún script se ejecuta en CYBER (solo queda en la bitácora); las consultas sí. Lo pone y lo quita ops.sp_prueba_modo; 0 en producción');
INSERT INTO cfg.PARAMETRO (CLIENTE, CLAVE, VALOR, DESCRIPCION) VALUES (N'486', N'RUTA_SALIDA', N'C:\BANBAJ\486\SALIDA\', N'ops.sp_exportar_salidas: carpeta de los archivos planos (se crea <AAAAMMDD>_corrida<ID>)');
INSERT INTO cfg.PARAMETRO (CLIENTE, CLAVE, VALOR, DESCRIPCION) VALUES (N'486', N'RETROCESO_AUTOMATICO', N'1', N'1 = si una corrida falla, el DAT, histórico, folios y base maestra regresan solos a como estaban (ops.sp_retroceso_automatico); 0 = se dejan para revisar a mano');
INSERT INTO cfg.PARAMETRO (CLIENTE, CLAVE, VALOR, DESCRIPCION) VALUES (N'486', N'RUTA_MIS', N'\\192.168.50.13\q\MIS\SERTEC98\CLIENTES\486\', N'ops.sp_exportar_salidas deja aquí también DAT486_<fecha>.csv (antes prog15.prg copiaba el DAT). Q: = \\192.168.50.13\q');
INSERT INTO cfg.PARAMETRO (CLIENTE, CLAVE, VALOR, DESCRIPCION) VALUES (N'486', N'CARPETA_ZIP', N'C:\', N'ops.sp_exportar_salidas: carpeta del ZIP de retiros (C:\RETIROS_PAG_486_<fecha><hora>.zip, como saldos.prg)');
INSERT INTO cfg.PARAMETRO (CLIENTE, CLAVE, VALOR, DESCRIPCION) VALUES (N'486', N'RUTA_7ZIP', N'C:\Program Files\7-Zip\7z.exe', N'7-Zip instalado en el servidor de SQL Server (ZIP con contraseña de retiros)');
INSERT INTO cfg.PARAMETRO (CLIENTE, CLAVE, VALOR, DESCRIPCION) VALUES (N'486', N'CYBER_LINKED_SERVER', N'CYBER', N'Servidor vinculado a Oracle (cfg.sp_cyber_conectar / ops.sp_bajar_cyber)');
INSERT INTO cfg.PARAMETRO (CLIENTE, CLAVE, VALOR, DESCRIPCION) VALUES (N'486', N'CYBER_ORACLE_ORIGEN', N'', N'PENDIENTE: Oracle de CYBER como host:puerto/servicio (ej. 10.0.0.5:1521/servicio)');
INSERT INTO cfg.PARAMETRO (CLIENTE, CLAVE, VALOR, DESCRIPCION) VALUES (N'486', N'CYBER_ORACLE_PROVEEDOR', N'OraOLEDB.Oracle', N'Proveedor OLE DB de Oracle instalado en el servidor de SQL Server');
INSERT INTO cfg.PARAMETRO (CLIENTE, CLAVE, VALOR, DESCRIPCION) VALUES (N'486', N'CYBER_PROC_TELEFONOS', N'RCVRY.JSP_TELEFONOS_REMESA_486', N'Procedimiento de CYBER que purga y agrega los teléfonos (ACTUALIZA_PHONE.SQL) con TEL_DEPURACION = ACTUAL');
INSERT INTO cfg.PARAMETRO (CLIENTE, CLAVE, VALOR, DESCRIPCION) VALUES (N'486', N'TEL_VALIDAR_LADA', N'1', N'1 (19/11) = solo van a CYBER (SCBTEL y remesa) los teléfonos cuya lada y longitud están en cfg.PHNVAL, la copia de la tabla de ladas que admite el cargador; 0 = no se revisa');
INSERT INTO cfg.PARAMETRO (CLIENTE, CLAVE, VALOR, DESCRIPCION) VALUES (N'486', N'CYBER_TABLA_LADAS', N'RCVRY.PHNVAL', N'Tabla de CYBER con las ladas válidas (VTCOMUNA, VTARECOD, VTLENGTH) que copia ops.sp_phnval_actualizar una vez al mes');
INSERT INTO cfg.PARAMETRO (CLIENTE, CLAVE, VALOR, DESCRIPCION) VALUES (N'486', N'LADAS_MIN_FILAS', N'100', N'Si la tabla de ladas de CYBER llega con menos renglones que esto, no se toca cfg.PHNVAL (protege contra una bajada vacía o cortada)');
INSERT INTO cfg.PARAMETRO (CLIENTE, CLAVE, VALOR, DESCRIPCION) VALUES (N'486', N'TEL_DEPURACION', N'ACTUAL', N'ACTUAL = remesa completa y store de hoy (CYBER_PROC_TELEFONOS); SCBTEL con todos. DIFERENCIA (19/11, cuando el DBA instale RCVRY.JSP_TAB_TEL_DEPURA_486 y JSP_TELEFONOS_DEPURA_486) = se baja la foto de PHONE, se compara aquí y a CYBER solo sube lo que cambia; el SCBTEL lleva solo los nuevos');
INSERT INTO cfg.PARAMETRO (CLIENTE, CLAVE, VALOR, DESCRIPCION) VALUES (N'486', N'CYBER_PROC_TEL_DEPURA', N'RCVRY.JSP_TELEFONOS_DEPURA_486', N'Store de depuración de teléfonos con TEL_DEPURACION = DIFERENCIA (cyber/486/oracle/JSP_TELEFONOS_DEPURA_486.sql)');
INSERT INTO cfg.PARAMETRO (CLIENTE, CLAVE, VALOR, DESCRIPCION) VALUES (N'486', N'CYBER_BANDERA_TELEFONOS', N'416', N'id_proc de RCVRY.RPT_LOG_CYBER_REG que se enciende antes de la depuración de teléfonos y se apaga al terminar o si falla (bitácora en RCVRY.RPT_LOG_CYBER); la misma de los correos');
INSERT INTO cfg.PARAMETRO (CLIENTE, CLAVE, VALOR, DESCRIPCION) VALUES (N'486', N'TEL_GESTORES_QUEJA', N'HOMS,HPHPI,BLACK,ZZZTE', N'Gestores (PHSTCOLLID) de queja: con TEL_DEPURACION = DIFERENCIA sus teléfonos no se inactivan ni se activan');
INSERT INTO cfg.PARAMETRO (CLIENTE, CLAVE, VALOR, DESCRIPCION) VALUES (N'486', N'TEL_DEPURA_MAX_INACTIVAR_PCT', N'30', N'Con TEL_DEPURACION = DIFERENCIA, si se inactivaría más de este % de los teléfonos activos de la foto de CYBER, no se toca CYBER y llega un hallazgo');
