USE [BNABAJ_486];   -- base del 486 (si la instalas con otro nombre, cámbialo aquí)
GO
/* =====================================================================
   Banbaj · 90 Semilla del cliente 486 (generado por tools/generar_sql_486.py)
   Re-ejecutable: borra y vuelve a cargar la configuración del 486.
   Revisar antes de producción: RUTA de cfg.ARCHIVO, PERFIL_DBMAIL,
   TOPE_DEVOLUCION_PCT y los campos marcados POR CONFIRMAR / PENDIENTE.
   ===================================================================== */
SET NOCOUNT ON;
SET XACT_ABORT ON;
BEGIN TRANSACTION;
/* Lo que cambia la semilla no cuenta como cambio del equipo (triggers de cfg.ARCHIVO, cfg.ARCHIVO_COLUMNA, cfg.CATALOGO).
   Si la semilla fallara a medias, cierra la ventana de SSMS antes de editar el layout a mano. */
EXEC sp_set_session_context @key = N'SEMILLA', @value = 1;

/* Layout que cambió el equipo de asignaciones (decisión 17/11): se guarda y se repone después de recargar */
DROP TABLE IF EXISTS #arch_equipo; DROP TABLE IF EXISTS #col_equipo;
SELECT CODIGO, RUTA, PATRON_NOMBRE, ACTIVO, OBLIGATORIO, EDITADO_POR, FE_EDICION INTO #arch_equipo FROM cfg.ARCHIVO WHERE CLIENTE = N'486' AND EDITADO_POR IS NOT NULL;
SELECT a.CODIGO, c.CAMPO_DESTINO, c.PATRON_ENCABEZADO, c.POSICION, c.ACTIVO, c.OBLIGATORIO, c.PERMITE_VACIO, c.EDITADO_POR, c.FE_EDICION
INTO #col_equipo FROM cfg.ARCHIVO_COLUMNA c JOIN cfg.ARCHIVO a ON a.ID_ARCHIVO = c.ID_ARCHIVO WHERE a.CLIENTE = N'486' AND c.EDITADO_POR IS NOT NULL;
DELETE c FROM cfg.ARCHIVO_COLUMNA c JOIN cfg.ARCHIVO a ON a.ID_ARCHIVO = c.ID_ARCHIVO WHERE a.CLIENTE = N'486';
DELETE FROM cfg.ARCHIVO WHERE CLIENTE = N'486';
DELETE FROM cfg.HOMOLOGACION WHERE CLIENTE = N'486';
DELETE FROM cfg.REGLA WHERE CLIENTE = N'486';
DELETE FROM cfg.SALIDA WHERE CLIENTE = N'486';
DELETE FROM cfg.SALIDA_ARCHIVO WHERE CLIENTE = N'486';
DELETE FROM cfg.PARAMETRO WHERE CLIENTE = N'486';
DELETE FROM cfg.CP_ESTADO;
-- Correos retirados (decisiones 29 y 30/10)
DELETE FROM mail.PLANTILLA WHERE CODIGO IN (N'ASIG_EXPRESS_486', N'PAGOS_NO_ACTUALIZADOS_486', N'RETIROS_ACT_486', N'AVISO_DEVOLUCION_486', N'NOTIFICACION_RETIRO_486', N'CONFIRMACION_ACT_486', N'ERROR_PROCESO_486', N'DEVOLUCION_MASIVA_486', N'SALDOS_NO_ACTUALIZADOS_486', N'SALDOS_IGUALES_DAT_486', N'PAGOS_NO_SUBIERON_486');
DELETE FROM mail.DESTINATARIO WHERE LISTA IN (N'OPERACION_PAGOS_486', N'ASIG_EXPRESS_486', N'PAGOS_NO_ACTUALIZADOS_486', N'RETIROS_ACT_486', N'ACTUALIZACION_486', N'RETIROS_OPERACION_486');
DELETE FROM mail.LISTA WHERE CODIGO IN (N'OPERACION_PAGOS_486', N'ASIG_EXPRESS_486', N'PAGOS_NO_ACTUALIZADOS_486', N'RETIROS_ACT_486', N'ACTUALIZACION_486', N'RETIROS_OPERACION_486');
DELETE FROM mail.DESTINATARIO WHERE LISTA = N'DEVOLUCION_AEM_486';   -- antes TO/CC, ahora todo en copia oculta
UPDATE mail.PLANTILLA SET PERFIL_DBMAIL = N'asig.486.cdmx' WHERE CODIGO LIKE N'%486%';

/* Parámetros */

/* CP -> estado */

/* Archivos de entrada y sus columnas */
DECLARE @id INT;
SET @id = SCOPE_IDENTITY();

SET @id = SCOPE_IDENTITY();

