FROM cfg.ARCHIVO_COLUMNA c JOIN cfg.ARCHIVO a ON a.ID_ARCHIVO = c.ID_ARCHIVO
JOIN #col_equipo e ON e.CODIGO = a.CODIGO AND e.CAMPO_DESTINO = c.CAMPO_DESTINO WHERE a.CLIENTE = N'486';
